if (!msg.payload.device_id || !msg.payload.timestamp) {
    node.warn('Missing required fields');
    return null;
}

let count = context.get('messageCount') || 0;
count++;
context.set('messageCount', count);

msg.enriched = {
    ...msg.payload,
    processed_at: new Date().toISOString(),
    node_red_version: '1.0',
    topic_original: msg.topic,
    data_quality: { valid: true, latency_ms: Date.now() - (msg.payload.timestamp * 1000) }
};

node.status({ fill: 'green', shape: 'dot', text: `${msg.payload.device_id} (${count})` });
return msg;

msg.payload = { ...msg.enriched, category: 'PLC', priority: 'high' };
msg.topic = 'collector/ingest';
return msg;

msg.payload = { ...msg.enriched, category: 'Sensor', priority: 'medium' };
msg.topic = 'collector/ingest';
return msg;

// Filter: Ensure we only process data if it has a value
if (!msg.payload || typeof msg.payload.value === 'undefined') return null;

let addr = msg.payload.address;
let val = msg.payload.value;

// Debug log to confirm we received the write
node.warn("Modbus Write Received -> Addr: " + addr + " | Value: " + val);

// --- UNPACKING LOGIC FOR REGISTER 9 ---
if (addr === 9) {
    // Decode the Integer into Booleans
    // (val & 1) checks bit 0, (val & 2) checks bit 1, etc.
    let c1_active = (val & 1) > 0;  // Bit 0 (Decimal 1)
    let c2_active = (val & 2) > 0;  // Bit 1 (Decimal 2)
    let p1_active = (val & 4) > 0;  // Bit 2 (Decimal 4)
    let p1_ready  = (val & 8) > 0;  // Bit 3 (Decimal 8)

    // Send 3 separate commands to your Unreal/Collector flow
    // We send an array of 3 messages
    return [
        { 
            topic: "factory/command/Conveyor1", 
            payload: { is_on: c1_active } 
        },
        { 
            topic: "factory/command/Conveyor2", 
            payload: { is_on: c2_active } 
        },
        { 
            topic: "factory/command/Placer1", 
            payload: { is_on: p1_active, is_ready: p1_ready } 
        }
    ];
}

return null;

let c1 = flow.get('c1_rpm') || 0;
let c2 = flow.get('c2_rpm') || 0;
let px = flow.get('placer_x') || 0;
let py = flow.get('placer_y') || 0;
let c1_on = flow.get('c1_on') || false;
let c2_on = flow.get('c2_on') || false;
let p1_ready = flow.get('p1_ready') || false;
let simActive = false; // Force to true for testing

if (msg.payload && msg.topic !== 'tick' && !simActive) {
    try {
        let data = JSON.parse(msg.payload.toString().replace(/\.\s*"/g, ',"').replace(/(\d),\s*(\d)/g, '$1$2'));
        let dev = msg.topic.split('/').pop();
        if (dev === 'Conveyor1') { flow.set('c1_rpm', data.rpm); flow.set('c1_on', data.is_on); }
        if (dev === 'Conveyor2') { flow.set('c2_rpm', data.rpm); flow.set('c2_on', data.is_on); }
        if (dev === 'Placer1') { flow.set('placer_x', data.posX); flow.set('placer_y', data.posY); flow.set('p1_ready', data.is_ready); }
        node.send([null, { topic: 'collector/ingest', payload: { device: dev, data: data, type: 'UNREAL' } }]);
    } catch(e) {}
}

if (msg.topic === 'tick') {
    if (simActive) {
        c1 = Math.floor(Math.random() * 4000) + 1000;
        c2 = Math.floor(Math.random() * 4000) + 1000;
        px = Math.floor(Math.random() * 101); py = Math.floor(Math.random() * 101);
        c1_on = true; p1_ready = true;
        node.send([null, { topic: 'collector/ingest', payload: { type: 'MOCK', c1, c2, px, py } }]);
    }
    let mask = 0;
    if (c1_on) mask |= (1 << 0); if (c2_on) mask |= (1 << 1); if (p1_ready) mask |= (1 << 3);
    let buf = Buffer.alloc(10);
    buf.writeUInt16BE(c1, 0); buf.writeUInt16BE(c2, 2); buf.writeUInt16BE(px, 4); buf.writeUInt16BE(py, 6); buf.writeUInt16BE(mask, 8);
    return [{ payload: { value: buf, register: 'holding', address: 1, disableMsgOutput: 1 } }, null];
}
return null;

// Split MOCK UNREAL data into 3 individual device messages
if (msg.payload.type === 'MOCK' || msg.payload.type === 'UNREAL') {
    let timestamp = Date.now() / 1000;
    let c1 = msg.payload.c1 || 0;
    let c2 = msg.payload.c2 || 0;
    let px = msg.payload.px || 0;
    let py = msg.payload.py || 0;

    let metadata = {
        tenant: 'accenture',
        factory: 'test_factory',
        processed_at: new Date().toISOString(),
        category: 'UNREAL',
        priority: 'medium'
    };

    // Create 3 separate device messages
    let devices = [
        {
            device_id: 'conveyor1',
            type: 'UNREAL',
            timestamp: timestamp,
            data: {
                rpm: c1,
                is_on: true
            },
            metadata: metadata
        },
        {
            device_id: 'conveyor2',
            type: 'UNREAL',
            timestamp: timestamp,
            data: {
                rpm: c2,
                is_on: true
            },
            metadata: metadata
        },
        {
            device_id: 'placer',
            type: 'UNREAL',
            timestamp: timestamp,
            data: {
                posX: px,
                posY: py,
                is_on: true,
                is_ready: true
            },
            metadata: metadata
        }
    ];

    // Send each device as a separate message
    devices.forEach(dev => {
        node.send({ topic: 'collector/ingest', payload: dev });
    });

    return null; // Don't forward the original MOCK message
}

// For other messages, just add metadata
msg.topic = 'collector/ingest';
msg.payload = { ...msg.payload, category: 'UNREAL_PIPE', processed_at: new Date().toISOString() };
return msg;
